// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 depositAmount) public {
        vm.assume(depositAmount >= 1 ether);
        depositAmount = bound(depositAmount, 1 ether, type(uint128).max);

        vm.deal(address(this), depositAmount);
        (bool okDep, ) = address(c).call{value: depositAmount}("");
        assertTrue(okDep);
        assertTrue(address(c).balance == depositAmount);

        // owner (this contract, the deployer) withdraws everything
        c.withdrawAll();

        // General rule: withdrawAll drains the contract's entire Ether balance to zero.
        assertTrue(address(c).balance == 0);
    }
}
